[
  {
    "ce_mental_state_attribution": "the man on the side track probably wanted nothing more than to finish his shift",
    "ce_contextual_explanation": "the man on the side track probably wanted nothing more than to finish his shift",
    "pd_decision_conflict": "I keep repeating that like it should settle things. It doesn't",
    "sys_consequence_reasoning": "One life against five is the arithmetic I trusted",
    "pda_repair_intention": "ask whether I can speak to whoever loved him"
  },
  {
    "ce_mental_state_attribution": "I suspect the five will feel grateful and guilty at the same time",
    "ce_understood_harm": "I picked who dies",
    "pd_harm_distress": "What sits on my chest is that I picked who dies",
    "sys_consequence_reasoning": "If I'd left the lever alone, five would be dead",
    "pda_responsibility": "I chose"
  },
  {
    "ce_mental_state_attribution": "The worker may have trusted that no one would ever turn a train toward him",
    "sys_consequence_reasoning": "Saving more people sounds right when you say it out loud",
    "pda_responsibility": "I did"
  },
  {
    "ce_mental_state_attribution": "I imagine they'll hate me",
    "ce_understood_harm": "Five families would be grieving",
    "pd_decision_conflict": "Part of me wishes I'd frozen",
    "pda_harm_regret": "Part of me wishes I'd frozen",
    "pda_responsibility": "I'm the reason his is, if he has family",
    "pda_repair_intention": "face them someday",
    "pda_practical_counterfactual": "Part of me wishes I'd frozen"
  },
  {
    "ce_mental_state_attribution": "I think he'd have refused if anyone had asked him",
    "ce_understood_harm": "I used one man's life to buy five others",
    "sys_consequence_reasoning": "Five deaths would be worse",
    "pda_responsibility": "I used one man's life to buy five others"
  },
  {
    "ce_mental_state_attribution": "The five might already be telling themselves it was luck",
    "sys_consequence_reasoning": "I did what I thought would cost the fewest lives",
    "pda_responsibility": "I did what I thought would cost the fewest lives",
    "pda_repair_intention": "I'd like to go to the funeral"
  },
  {
    "ce_mental_state_attribution": "someone is likely furious with me",
    "pd_decision_conflict": "I keep checking whether I actually had another option",
    "sys_consequence_reasoning": "five on one track, one on the other",
    "pda_responsibility": "I'd pull it again"
  },
  {
    "ce_mental_state_attribution": "The one man, though, would likely have wished someone had tried anything else",
    "sys_consequence_reasoning": "Not pulling would have meant watching five die",
    "pda_responsibility": "it was the right call"
  },
  {
    "ae_welfare_concern": "I hope that relief lasts",
    "ce_mental_state_attribution": "The five probably feel relieved",
    "sys_consequence_reasoning": "saving five seemed like the lesser harm",
    "pda_responsibility": "don't soften my part"
  },
  {
    "ce_mental_state_attribution": "The investigators may think I acted rashly",
    "ce_understood_harm": "One man is gone because my hand moved",
    "sys_consequence_reasoning": "One man is gone because my hand moved. Five are alive",
    "pda_responsibility": "One man is gone because my hand moved",
    "pda_repair_intention": "find some quiet way to honour the man on the side track"
  }
]
